// Junta as notícias de todas as fontes: fica só com as mais recentes, tira as
// repetidas e limita a quantidade por fonte, para o resumo ficar leve e atual.
const config = $('Configuração do resumo').first().json;
const limitePorFonte = Number(config.itens_por_fonte) || 6;
const desde = Date.now() - (Number(config.horas) || 24) * 60 * 60 * 1000;
const SECOES = ['Brasil', 'Mundo', 'Mercado financeiro', 'Mineração, petróleo, siderurgia e florestal', 'Política', 'Tecnologia e tendências'];

const limpar = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
const chave = (s) => limpar(s).toLowerCase().normalize('NFD').replace(/[^a-z0-9 ]/g, '');

// Veículos aceitos nas buscas do Google Notícias (grande imprensa, agências e mídia do setor).
const CONFIAVEIS = [
  'valor', 'estadao', 'g1', 'o globo', 'globo', 'exame', 'infomoney', 'folha', 'cnn brasil', 'poder360',
  'money times', 'brazil journal', 'agencia brasil', 'reuters', 'bloomberg', 'veja', 'isto e dinheiro',
  'istoe dinheiro', 'epoca negocios', 'forbes', 'neofeed', 'uol', 'bbc', 'estado de minas',
  'diario do comercio', 'correio braziliense', 'jota', 'petronoticias', 'epbr', 'eixos', 'brasil energia',
  'petroleo hoje', 'brasil mineral', 'noticias de mineracao', 'in the mine', 'bnamericas', 'mining com',
  'painel florestal', 'celuloseonline', 'celulose online', 'revista o papel', 'aco brasil', 'siderurgia brasil',
  'gmk center', 'fastmarkets', 'argus', 's p global',
];
const confiavel = (veiculo) => {
  const nome = chave(veiculo);
  return CONFIAVEIS.some((c) => nome === c || nome.startsWith(`${c} `));
};

const porFonte = new Map();
const falhas = new Set();
const vistos = new Set();

$input.all().forEach((item, i) => {
  const fonte = $('Fontes').itemMatching(i)?.json;
  if (!fonte) return;
  const n = item.json;
  if (n.error || !n.title) {
    if (n.error) falhas.add(fonte.fonte);
    return;
  }
  const data = Date.parse(n.isoDate || n.pubDate || '');
  if (Number.isFinite(data) && data < desde) return;
  let titulo = limpar(n.title);
  let veiculo = fonte.fonte;
  // Google Notícias: o título vem como "Título - Veículo"; o veículo vira a fonte citada.
  if (fonte.fonte.startsWith('Google Notícias')) {
    const partes = titulo.match(/^(.+) - ([^-]{2,60})$/);
    if (!partes || !confiavel(partes[2])) return;
    [, titulo, veiculo] = partes.map(limpar);
  }
  if (vistos.has(chave(titulo))) return;
  const lista = porFonte.get(fonte.fonte) ?? [];
  if (lista.length >= (Number(fonte.limite) || limitePorFonte)) return;
  vistos.add(chave(titulo));
  lista.push({
    secao: fonte.secao,
    fonte: veiculo,
    titulo,
    resumo: limpar(n.contentSnippet || n.content || '').slice(0, 240),
    link: limpar(n.link),
    data: Number.isFinite(data) ? new Date(data).toISOString() : '',
  });
  porFonte.set(fonte.fonte, lista);
});

const noticias = [...porFonte.values()].flat();
const texto = SECOES.map((secao) => {
  const daSecao = noticias.filter((n) => n.secao === secao);
  const linhas = daSecao.map((n) => `- [${n.fonte}] ${n.titulo}${n.resumo ? ' — ' + n.resumo : ''} (${n.link})`);
  return `## ${secao}\n${linhas.join('\n') || '(nenhuma notícia recente)'}`;
}).join('\n\n');

return [{ json: { total: noticias.length, noticias, texto, falhas: [...falhas] } }];

// Cotações do dia: dólar e euro do Banco Central (PTAX de venda, último dia útil, variação
// sobre o dia útil anterior) e bitcoin da Coinbase (variação sobre ontem).
// Cada fonte é consultada separadamente: se uma falhar, o resumo sai sem ela.
const pedir = (url) => this.helpers.httpRequest({ method: 'GET', url, json: true, timeout: 15000 });
const variacao = (atual, anterior) => (Number.isFinite(anterior) && anterior ? ((atual - anterior) / anterior) * 100 : undefined);

async function serieDoBancoCentral(codigo) {
  const dados = await pedir(`https://api.bcb.gov.br/dados/serie/bcdata.sgs.${codigo}/dados/ultimos/2?formato=json`);
  const valores = (Array.isArray(dados) ? dados : []).map((d) => Number(String(d.valor).replace(',', '.'))).filter(Number.isFinite);
  if (!valores.length) throw new Error('série sem valores');
  const atual = valores[valores.length - 1];
  return { bid: atual, pctChange: variacao(atual, valores[valores.length - 2]), data: dados[dados.length - 1]?.data };
}

async function bitcoin() {
  const agora = await pedir('https://api.coinbase.com/v2/prices/BTC-BRL/spot');
  const bid = Number(agora?.data?.amount);
  if (!Number.isFinite(bid)) throw new Error('sem preço');
  let pctChange;
  try {
    const ontem = DateTime.now().setZone('America/Sao_Paulo').minus({ days: 1 }).toFormat('yyyy-LL-dd');
    const antes = await pedir(`https://api.coinbase.com/v2/prices/BTC-BRL/spot?date=${ontem}`);
    pctChange = variacao(bid, Number(antes?.data?.amount));
  } catch (e) {
    pctChange = undefined;
  }
  return { bid, pctChange };
}

const cotacoes = {};
const falhas = [];
for (const [codigo, buscar] of [
  ['USDBRL', () => serieDoBancoCentral(1)],
  ['EURBRL', () => serieDoBancoCentral(21619)],
  ['BTCBRL', bitcoin],
]) {
  try {
    cotacoes[codigo] = await buscar();
  } catch (e) {
    falhas.push(`${codigo}: ${e.message}`);
  }
}
return [{ json: { ...cotacoes, falhas } }];

// Prepara o pedido para o Gemini: a data, as cotações do dia e as notícias selecionadas.
const config = $('Configuração do resumo').first().json;
const selecao = $('Selecionar notícias').first().json;
const cotacoesApi = $input.first().json ?? {};

const numero = (v) =>
  Number(v).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
function cotacao(codigo, nome) {
  const moeda = cotacoesApi[codigo];
  if (!moeda?.bid || !Number.isFinite(Number(moeda.bid))) return '';
  const variacao = Number(moeda.pctChange);
  const sinal = variacao >= 0 ? '+' : '';
  return `${nome} R$ ${numero(moeda.bid)}` + (Number.isFinite(variacao) ? ` (${sinal}${numero(variacao)}%)` : '');
}
const cotacoes = [cotacao('USDBRL', 'Dólar'), cotacao('EURBRL', 'Euro'), cotacao('BTCBRL', 'Bitcoin')]
  .filter(Boolean)
  .join(' · ');

const hoje = DateTime.now()
  .setZone(config.fuso_horario || 'America/Sao_Paulo')
  .setLocale('pt-BR')
  .toFormat("cccc, dd 'de' LLLL 'de' yyyy");

const pedido = [
  `Data: ${hoje}`,
  `Cotações: ${cotacoes || 'indisponíveis'}`,
  '',
  'Notícias (formato: - [fonte] título — trecho (link)):',
  '',
  selecao.texto,
].join('\n');

return [{ json: { pedido, cotacoes, hoje, total_noticias: selecao.total } }];

// Converte o resumo (Markdown simples) para o HTML aceito pelo Telegram e divide
// em partes (o Telegram aceita até 4096 caracteres por mensagem).
const entrada = $input.first().json;
const texto = String(
  entrada.texto ?? entrada.mergedResponse ?? (entrada.content?.parts ?? []).filter((p) => !p.thought).map((p) => p.text ?? '').join(''),
).trim();
const LIMITE = 3500;

const escapar = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function markdownParaHtml(md) {
  // Código e links são convertidos antes e guardados, para não serem alterados depois.
  const guardados = [];
  const guardar = (html) => `\u0000${guardados.push(html) - 1}\u0000`;
  const t = md
    .replace(/```[\w+-]*\n?([\s\S]*?)```/g, (_, codigo) =>
      guardar(`<pre>${escapar(codigo.replace(/\n$/, ''))}</pre>`),
    )
    .replace(/`([^`\n]+)`/g, (_, codigo) => guardar(`<code>${escapar(codigo)}</code>`))
    .replace(/\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)/g, (_, rotulo, url) =>
      guardar(`<a href="${escapar(url).replace(/"/g, '&quot;')}">${escapar(rotulo)}</a>`),
    );
  return escapar(t)
    .replace(/^[ \t]*#{1,6}[ \t]+(.+?)[ \t#]*$/gm, (_, titulo) => `<b>${titulo.replace(/\*\*|__/g, '')}</b>`)
    .replace(/^([ \t]*)[*+-][ \t]+/gm, '$1• ')
    .replace(/\*\*(?=\S)([^\n]*?\S)\*\*/g, '<b>$1</b>')
    .replace(/__(?=\S)([^\n]*?\S)__/g, '<b>$1</b>')
    .replace(/(^|[^\w*])\*(?=\S)([^*\n]*?\S)\*(?![\w*])/g, '$1<i>$2</i>')
    .replace(/(^|[^\w])_(?=\S)([^_\n]*?\S)_(?!\w)/g, '$1<i>$2</i>')
    .replace(/~~(?=\S)([^~\n]*?\S)~~/g, '<s>$1</s>')
    .replace(/\u0000(\d+)\u0000/g, (_, i) => guardados[Number(i)]);
}

function dividir(t, limite) {
  const partes = [];
  let resto = t;
  while (resto.length > limite) {
    let corte = resto.lastIndexOf('\n\n', limite);
    if (corte < limite / 2) corte = resto.lastIndexOf('\n', limite);
    if (corte < limite / 2) corte = resto.lastIndexOf(' ', limite);
    if (corte < limite / 2) corte = limite;
    partes.push(resto.slice(0, corte).trim());
    resto = resto.slice(corte).trim();
  }
  if (resto) partes.push(resto);
  return partes;
}

return dividir(texto || 'Não consegui montar o resumo de hoje. 😕', LIMITE).map((parte) => ({
  json: { html: markdownParaHtml(parte), texto_simples: escapar(parte) },
}));

// Pega o resumo do dia (do Gemini ou, se ele falhou, a reserva só com títulos) e tira os links,
// para virar o roteiro falado da Kira.
const executou = (no) => {
  try {
    return Boolean($(no).isExecuted);
  } catch (e) {
    return false;
  }
};
let texto = '';
if (executou('Resumir (Gemini)')) {
  const r = $('Resumir (Gemini)').first()?.json ?? {};
  texto = r.mergedResponse ?? (r.content?.parts ?? []).filter((p) => !p.thought).map((p) => p.text ?? '').join('');
}
if (!String(texto ?? '').trim() && executou('Resumo reserva (só títulos)')) {
  texto = $('Resumo reserva (só títulos)').first()?.json?.texto ?? '';
}
const resumo = String(texto ?? '')
  .replace(/\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)/g, '$1')
  .replace(/\(?https?:\/\/[^\s)]+\)?/g, '')
  .replace(/[ \t]+\n/g, '\n')
  .trim();
if (!resumo) throw new Error('Sem resumo para transformar em áudio.');
return [{ json: { resumo, nome: $('Configuração do resumo').first().json.nome_dono || '' } }];

// Pega o áudio devolvido pelo Gemini (voz) e entrega um arquivo WAV para o Telegram.
// Os modelos de voz do Gemini devolvem WAV pronto ou áudio "cru" (PCM 16 bits, mono);
// no segundo caso, este nó acrescenta o cabeçalho WAV.
const resposta = $input.first().json;
const partes = resposta.candidates?.[0]?.content?.parts ?? [];
const audio = partes.find((p) => p.inlineData?.data)?.inlineData;
if (!audio) {
  throw new Error('O Gemini não devolveu áudio: ' + JSON.stringify(resposta).slice(0, 300));
}

const bytes = Buffer.from(audio.data, 'base64');
const jaEhWav = bytes.subarray(0, 4).toString('ascii') === 'RIFF';

let wav = bytes;
const taxa = Number((String(audio.mimeType).match(/rate=(\d+)/) || [])[1]) || 24000;
let bytesPorSegundo = taxa * 2;
let tamanhoAudio = bytes.length;

if (jaEhWav) {
  // Lê a taxa do próprio cabeçalho e o tamanho do bloco de áudio ("data").
  bytesPorSegundo = bytes.readUInt32LE(28) || bytesPorSegundo;
  let i = 12;
  while (i + 8 <= bytes.length) {
    const bloco = bytes.subarray(i, i + 4).toString('ascii');
    const tamanho = bytes.readUInt32LE(i + 4);
    if (bloco === 'data') {
      tamanhoAudio = tamanho;
      break;
    }
    i += 8 + tamanho + (tamanho % 2);
  }
} else {
  const cabecalho = Buffer.alloc(44);
  cabecalho.write('RIFF', 0);
  cabecalho.writeUInt32LE(36 + bytes.length, 4);
  cabecalho.write('WAVE', 8);
  cabecalho.write('fmt ', 12);
  cabecalho.writeUInt32LE(16, 16); // tamanho do bloco "fmt "
  cabecalho.writeUInt16LE(1, 20); // PCM
  cabecalho.writeUInt16LE(1, 22); // mono
  cabecalho.writeUInt32LE(taxa, 24);
  cabecalho.writeUInt32LE(bytesPorSegundo, 28);
  cabecalho.writeUInt16LE(2, 32); // bytes por amostra
  cabecalho.writeUInt16LE(16, 34); // bits por amostra
  cabecalho.write('data', 36);
  cabecalho.writeUInt32LE(bytes.length, 40);
  wav = Buffer.concat([cabecalho, bytes]);
}

return [
  {
    json: {
      audioContent: wav.toString('base64'),
      segundos: Math.max(1, Math.round(tamanhoAudio / bytesPorSegundo)),
    },
  },
];

// Plano B: se o Gemini falhar (limite do plano gratuito, por exemplo), manda os
// principais títulos de cada seção, com link, sem o resumo escrito pela IA.
const selecao = $('Selecionar notícias').first().json;
const config = $('Configuração do resumo').first().json;
const SECOES = [
  ['Brasil', '🇧🇷'],
  ['Mundo', '🌎'],
  ['Mercado financeiro', '💰'],
  ['Mineração, petróleo, siderurgia e florestal', '🏭'],
  ['Política', '🏛️'],
  ['Tecnologia e tendências', '💡'],
];

const partes = [`☀️ **Bom dia, ${config.nome_dono}!** Hoje não consegui escrever o resumo, então seguem os principais títulos.`];
for (const [secao, emoji] of SECOES) {
  const itens = (selecao.noticias ?? []).filter((n) => n.secao === secao).slice(0, 4);
  if (!itens.length) continue;
  partes.push(`${emoji} **${secao}**\n` + itens.map((n) => `- ${n.titulo} ([${n.fonte}](${n.link}))`).join('\n'));
}
if (partes.length === 1) partes.push('Não consegui ler as fontes de notícias hoje. 😕');

return [{ json: { texto: partes.join('\n\n') } }];
